            folder.mkdir(parents=True, exist_ok=True)
        self.env = {**os.environ, "ETF_RISK_JOBS_DB": self.db, "ETF_RISK_KAFKA_BOOTSTRAP": self.bootstrap,
                    "ETF_RISK_JOBS_TOPIC": self.topic}
