    """P4: ok, flag (past flag_fraction) or stop (past stop_fraction); unknown without a reading."""
    if fraction is None:
        return "unknown"
    return "stop" if fraction > settings.stop_fraction else "flag" if fraction > settings.flag_fraction else "ok"


